import json,hashlib,struct
from pathlib import Path
p=Path('assets/castle_refit_v1/exterior'); f=p/'gothic_wall-GI.glb'; b=f.read_bytes();n=struct.unpack_from('<I',b,12)[0];g=json.loads(b[20:20+n]); acc=g['accessors']; ps=[q for m in g['meshes'] for q in m['primitives']];poses=[acc[q['attributes']['POSITION']] for q in ps];mn=[min(a['min'][i] for a in poses) for i in range(3)];mx=[max(a['max'][i] for a in poses) for i in range(3)];r=json.loads((p/'FINAL-READY.json').read_text());r['gothic_wall']={'file':str(f),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'triangles':sum(acc[q['indices']]['count']//3 for q in ps),'bounds':[mn,mx],'scale':max(y-x for x,y in zip(mn,mx)),'vertex_colors':any('COLOR_0' in q['attributes'] for q in ps),'revision':'v10-flat-road-top72.24'};(p/'FINAL-READY.json').write_text(json.dumps(r,indent=2));print(json.dumps(r['gothic_wall'],indent=2))
